 q=dict(id=uid,family_uid=f'M4U-9231-NP-{code}{family}',lesson=key,title=title,collection='short' if v==1 else 'variant',prompt_html=prompt,answer_html=answer,solution_html=solution,hint_html='<p>Identify independent or paired data and define the null parameter first. Preserve the direction of the alternative and give every requested sign count, rank sum or probability.</p>',marks=len(fields),difficulty=2 if family<3 else 3,fields=fields,parts=[dict(label='',marking_criteria=[dict(code='A1',marks=1,description_html='<p>Give the correct '+html.escape(f['label'].lower())+'.</p>') for f in fields])],verification=uid)
