def exact_sign(data,ref,alt):
 d=[s.Rational(x)-s.Rational(ref) for x in data];pos=sum(bool(z>0) for z in d);neg=sum(bool(z<0) for z in d);n=pos+neg;lower=s.Rational(sum(math.comb(n,j) for j in range(pos+1)),2**n);upper=s.Rational(sum(math.comb(n,j) for j in range(pos,n+1)),2**n);p=upper if alt=='greater' else lower if alt=='less' else min(1,2*min(lower,upper));return n,pos,neg,p
def ranks_signed(d):
 d=list(map(s.Rational,d));ordered=sorted(map(abs,d));assert len(set(ordered))==len(d) and all(d);r=[ordered.index(abs(z))+1 for z in d];wp=sum(a for a,z in zip(r,d) if z>0);wm=sum(a for a,z in zip(r,d) if z<0);return d,r,wp,wm
def signed_p(n,wp,alt):
 sums=[sum(j+1 for j in range(n) if mask>>j&1) for mask in range(2**n)];lo=s.Rational(sum(x<=wp for x in sums),len(sums));hi=s.Rational(sum(x>=wp for x in sums),len(sums));return hi if alt=='greater' else lo if alt=='less' else min(1,2*min(lo,hi))
for v,data in enumerate([[46,52,41,49,47,43,48,42,45,44],[48,51,46,54,47,49,53,45]],1):
 n,pos,neg,p=exact_sign(data,50,'two')
 add('sign','S',1,v,'All signs and the exact two-sided probability',r'<p>Independent observations from a continuous population are \(('+','.join(map(str,data))+r')\). For \(H_0:m=50\) against \(H_1:m\ne50\), give n, the number above 50, the number below 50 and the exact two-sided p-value.</p>',[field('n','Usable sample size',n),field('positive','Positive signs',pos),field('negative','Negative signs',neg),field('p','Two-sided p-value',p)],'<p>Count signs relative to 50. Under the null the positive count is binomial with probability 1/2; double the smaller inclusive tail and cap at 1.</p>',dict(kind='sign',data=data,reference=50,alternative='two'))
for v,(data,ref) in enumerate([(['1.8','2.1','.7','2.5','1.6','1.3','2.8','1.1'],'1'),(['2.1','3.2','1.8','2.7','3.5','1.4','2.6','2.3'],'2')],1):
 n,pos,neg,p=exact_sign(data,ref,'greater')
 add('sign','S',2,v,'A paired sign test above a threshold',r'<p>Independent matched trials have reductions \(('+','.join(data)+r')\). Test a population median reduction greater than '+ref+r'. Assume a continuous population of reductions. Give the positive and negative counts relative to '+ref+r', and the exact upper-tail p-value.</p>',[field('positive','Positive signs',pos),field('negative','Negative signs',neg),field('p','Upper-tail p-value',p)],'<p>Subtract the proposed median reduction, not zero. Count signs and use P(B≥b) for the claim of a larger median.</p>',dict(kind='sign',data=data,reference=ref,alternative='greater'))
for v,(n,b) in enumerate([(40,28),(36,24)],1):
 mu=s.Rational(n,2);var=s.Rational(n,4);num=b-s.Rational(1,2)-mu
 add('sign','S',3,v,'Normal moments and the corrected numerator',r'<p>A sign test has \(n='+str(n)+r'\) and positive count \(b='+str(b)+r'\). For an upper alternative use the normal approximation to \(B\sim\mathrm B(n,1/2)\). Give its mean, variance, the corrected numerator \(b-0.5-\mu\), and standard deviation exactly.</p>',[field('mean','Null mean',mu),field('variance','Null variance',var),field('numerator','Corrected numerator',num),field('denominator','Standard deviation',s.sqrt(var))],'<p>The binomial mean and variance are n/2 and n/4. The inclusive upper event begins at b−0.5; divide the corrected numerator by the standard deviation.</p>',dict(kind='sign_z',n=n,statistic=b,alternative='greater'))
for v,d in enumerate([['-.3','1.2','.6','-.9'],['-1.1','.2','.8','1.6']],1):
 ds,r,wp,wm=ranks_signed(d);fields=[field('r'+str(j+1),'Rank of deviation '+str(j+1),rank) for j,rank in enumerate(r)]+[field('wp','Positive rank sum',wp),field('wm','Negative rank sum',wm),field('T','Two-sided minimum',min(wp,wm))]
 add('signed','W',1,v,'Every rank and both sign sums',r'<p>Four non-zero deviations are \(('+','.join(d)+r')\). Rank their absolute magnitudes, from smallest to largest. Give every rank in the original order, W₊, W₋ and T=min(W₊,W₋).</p>',fields,'<p>Keep the original order when entering the ranks. Restore each deviation’s sign only after ranking its magnitude. The two sums must total 10.</p>',dict(kind='signed',differences=d,alternative='two'))
for v,d in enumerate([['-.6','.2','1.1','-.4','1.8','2.6'],['-.2','.5','.9','1.4','-2.1','3']],1):
 ds,r,wp,wm=ranks_signed(d);p=signed_p(len(d),wp,'two')
 add('signed','W',2,v,'A complete exact two-sided test calculation',r'<p>Independent deviations from a null median are \(('+','.join(d)+r')\). The population is continuous and symmetric, with no ties. Give W₊, W₋, T and the exact two-sided signed-rank p-value. Under the null all 64 sign assignments to ranks 1,…,6 are equally likely.</p>',[field('wp','Positive rank sum',wp),field('wm','Negative rank sum',wm),field('T','Two-sided minimum',min(wp,wm)),field('p','Two-sided p-value',p)],'<p>Enumerate or use the exact distribution of the rank sum. Add the two symmetric inclusive tails; this is not a binomial count of positive signs.</p>',dict(kind='signed',differences=d,alternative='two'))
for v,n in enumerate([16,20],1):
 mu=s.Rational(n*(n+1),4);var=s.Rational(n*(n+1)*(2*n+1),24);total=s.Rational(n*(n+1),2)
 add('signed','W',3,v,'Moments belong to the directional rank sum',r'<p>A signed-rank test has '+str(n)+r' non-zero deviations with no tied magnitudes. Give the null mean and variance of W₊ and the fixed value of W₊+W₋. Do not treat these as moments of the folded minimum.</p>',[field('mean','Mean of positive rank sum',mu),field('variance','Variance of positive rank sum',var),field('total','Total of both rank sums',total)],'<p>Use n(n+1)/4, n(n+1)(2n+1)/24 and n(n+1)/2 respectively.</p>',dict(kind='signed_moments',n=n))
for v,(a,b,ref) in enumerate([(['12','15','18','20'],['10.4','11.8','16.9','15.5'],'2'),(['18','20','22','25'],['15.8','19.7','21.1','23.4'],'1.5')],1):
 d=[s.Rational(x)-s.Rational(y)-s.Rational(ref) for x,y in zip(a,b)];ds,r,wp,wm=ranks_signed(d)
 add('paired','P',1,v,'Subtract the paired null before ranking',r'<p>Four independent pairs have A=\(('+','.join(a)+r')\) and B=\(('+','.join(b)+r')\). Define D=A−B. For null median change '+ref+r', give all four deviations \(D_i-'+ref+r'\), in order, and both signed-rank sums.</p>',[field('d'+str(i+1),'Adjusted deviation '+str(i+1),z) for i,z in enumerate(d)]+[field('wp','Positive rank sum',wp),field('wm','Negative rank sum',wm)],'<p>Subtract within each pair, subtract the proposed median change, then rank the absolute adjusted deviations. Ranking the unadjusted reductions would test a different null.</p>',dict(kind='signed',differences=list(map(str,d)),input_a=a,input_b=b,reference=ref,alternative='greater'))
for v,(d,index) in enumerate([([1,-2,3,4,-5,6,7,8],1),([1,2,-3,4,-5,6,7,-8],7)],1):
 new=d.copy();new[index]*=-1;_,_,wp,wm=ranks_signed(new)
 add('paired','P',2,v,'Correct a transposed pair at a zero null',r'<p>Zero-null paired differences are \(('+','.join(map(str,d))+r')\). Pair '+str(index+1)+r' was transposed, so that difference must have its sign reversed. Give the new W₊, W₋ and two-sided minimum.</p>',[field('wp','Corrected positive rank sum',wp),field('wm','Corrected negative rank sum',wm),field('T','Corrected minimum',min(wp,wm))],'<p>The zero-null absolute magnitudes are unchanged. Move the affected rank from one sign sum to the other; do not rerank unnecessarily.</p>',dict(kind='flip',differences=d,index=index))
for v,(a,b) in enumerate([(['4.5','5.3','3.8','6.1','4.9'],[258,282,234,348,264]),(['3','4','5','6','7'],[174,255,288,336,450])],1):
 d=[s.Rational(x)-s.Rational(y,60) for x,y in zip(a,b)];_,_,wp,wm=ranks_signed(d)
 add('paired','P',3,v,'Consistent units for paired ranks',r'<p>Before readings in minutes are \(('+','.join(a)+r')\); paired after readings in seconds are \(('+','.join(map(str,b))+r')\). For before minus after and a zero null, give W₊, W₋ and the usable number of pairs.</p>',[field('wp','Positive rank sum',wp),field('wm','Negative rank sum',wm),field('n','Usable number of pairs',len(a))],'<p>Convert seconds to minutes before subtraction. There is one difference per pair; the number of readings is not the signed-rank sample size.</p>',dict(kind='signed',differences=list(map(str,d)),input_a=a,input_b=b,scale_b='1/60',alternative='two'))
def independent(a,b):
 a=list(map(s.Rational,a));b=list(map(s.Rational,b));order=sorted(a+b);assert len(set(order))==len(order);ra=sum(order.index(x)+1 for x in a);rb=sum(order.index(x)+1 for x in b);reflection=len(a)*(len(a)+len(b)+1)-ra;return ra,rb,reflection,min(ra,reflection)
for v,(a,b) in enumerate([([4,8,9],[1,3,6,10]),([1,3,7],[2,4,5,6])],1):
 ra,rb,refl,W=independent(a,b)
 add('rank_sum','R',1,v,'The same sample’s reflected sum',r'<p>Independent groups have A=\(('+','.join(map(str,a))+r')\), B=\(('+','.join(map(str,b))+r')\). Rank them together in ascending order. A is the smaller sample. Give RA, RB, the reflected A sum and the MF19 statistic W.</p>',[field('ra','Ascending A rank sum',ra),field('rb','Ascending B rank sum',rb),field('reflected','Reflected A rank sum',refl),field('W','MF19 statistic',W)],'<p>Reverse the ranks for the same smaller sample: R*=m(m+n+1)−RA. Take min(RA,R*), not generally min(RA,RB).</p>',dict(kind='rank_sum',a=a,b=b,alternative='two'))
for v,(a,b) in enumerate([([6,8,10],[1,2,3,4]),([5,7,9],[1,2,3,6])],1):
 ra,rb,refl,W=independent(a,b);sums=list(map(sum,itertools.combinations(range(1,8),3)));p=s.Rational(sum(x>=ra for x in sums),len(sums))
 add('rank_sum','R',2,v,'An exact upper-tail allocation probability',r'<p>Independent samples have A=\(('+','.join(map(str,a))+r')\) and B=\(('+','.join(map(str,b))+r')\). Assume continuous symmetric populations of common shape, differing at most by location. Give RA and the exact p-value for A having the greater median. Under H₀ all C(7,3)=35 allocations are equally likely.</p>',[field('ra','Ascending A rank sum',ra),field('p','Upper-tail p-value',p)],'<p>Sum A’s pooled ascending ranks. Count all allocations with a rank sum at least as large; this is a one-sided probability, so do not double it.</p>',dict(kind='rank_sum',a=a,b=b,alternative='greater'))
for v,(m,n,stat,alt) in enumerate([(12,15,220,'greater'),(10,12,140,'less')],1):
 mu=s.Rational(m*(m+n+1),2);var=s.Rational(m*n*(m+n+1),12);cc=s.Rational(-1,2) if alt=='greater' else s.Rational(1,2);num=stat+cc-mu
 add('rank_sum','R',3,v,'Normal moments and the directional correction',r'<p>No-ties independent samples have sizes m='+str(m)+', n='+str(n)+r' and ascending rank sum R='+str(stat)+r' for the smaller sample. The alternative is that this sample’s population location is '+('greater' if alt=='greater' else 'smaller')+r'. Give the null mean, variance, corrected numerator, standard deviation and continuity adjustment exactly.</p>',[field('mean','Null rank-sum mean',mu),field('variance','Null rank-sum variance',var),field('numerator','Corrected numerator',num),field('denominator','Standard deviation',s.sqrt(var)),field('correction','Continuity adjustment',cc)],'<p>Use m(m+n+1)/2 and mn(m+n+1)/12. Upper-inclusive tails subtract 0.5; lower-inclusive tails add 0.5. Keep the direction of the alternative.</p>',dict(kind='rank_z',m=m,n=n,statistic=stat,alternative=alt))
choices={
'sign':[
 ('Which assumption is unnecessary?','<p>For a sign test of a continuous population median based on independent random observations, which extra assumption is not required?</p>',{'A':'Population symmetry.','B':'Independent observations.','C':'A defined null median.','D':'A suitable sampling design.'},'A','<p>Symmetry is needed for the usual signed-rank location test, but not for the sign test.</p>'),
 ('The paired parameter','<p>For a paired sign test of old-minus-new changes, what is the parameter?</p>',{'A':'Always the difference of the two marginal medians.','B':'The population median of individual paired changes.','C':'The sample mean of all readings mixed together.','D':'The number of positive observations itself.'},'B','<p>The distribution being tested is the distribution of individual differences.</p>')],
'signed':[
 ('What receives a rank?','<p>What should be ranked in the one-sample signed-rank test?</p>',{'A':'The original observations, ignoring the null.','B':'The signed deviations from most negative to most positive.','C':'The absolute deviations from the null median, retaining signs separately.','D':'Only the positive deviations.'},'C','<p>Every usable deviation contributes a magnitude rank and a separate sign.</p>'),
 ('A one-sided direction','<p>For H₁: m&lt;m₀, which signed-rank result supports the alternative?</p>',{'A':'A small W₊.','B':'A large W₊.','C':'Any small min(W₊,W₋), regardless of which sum is small.','D':'Only a large total W₊+W₋.'},'A','<p>A decrease produces mainly negative deviations; the positive rank sum should be unusually small.</p>')],
'paired':[
 ('Where is symmetry required?','<p>Which symmetry assumption supports a matched-pairs signed-rank median test?</p>',{'A':'Both marginal samples must be identical.','B':'The population of individual paired differences is symmetric about its median.','C':'The order of rows in the table must be symmetric.','D':'Only the before readings must be normal.'},'B','<p>The signed-rank procedure is applied to one sample of differences.</p>'),
 ('When can ranks stay unchanged?','<p>At a zero null, swapping the two readings in a single pair reverses its difference but leaves its absolute magnitude unchanged. What is needed?</p>',{'A':'Drop the pair.','B':'Double the sample size.','C':'Move its existing rank to the other sign sum.','D':'Use independent-sample rank sums instead.'},'C','<p>Only the sign changes in this stated zero-null case. A magnitude change would require reranking.</p>')],
'rank_sum':[
 ('Equal sample sizes','<p>Two independent samples contain the same number of observations. Does this justify pairing observations by row?</p>',{'A':'Yes, equal sizes create pairs.','B':'No; pairing needs a meaningful design, not matching row positions.','C':'Yes, provided the rows are sorted.','D':'Yes, if the rank sums differ.'},'B','<p>Use a procedure for independent samples unless the study actually contains matched units.</p>'),
 ('A median interpretation','<p>Which model supports the 9231 interpretation of a rank-sum test as a comparison of medians?</p>',{'A':'Any two distributions, whatever their shapes.','B':'Dependent samples with arbitrary shapes.','C':'Independent continuous symmetric populations of common shape and spread, differing at most by location.','D':'Only equal sample sizes, with no distributional assumptions.'},'C','<p>Without the common-shape location model, a distributional difference need not be a median difference.</p>')]
}
